content:
 — Tera échappe le HTML
      hors `safe`, ce qui est exactement ce que demande le XML ;
    - GUID = permalink de la page : ne jamais changer l'URL d'un article
      publié ;
    - un feed par section, une seule langue par feed (le futur /en/ aura
      le sien). -#}

  {% if section is defined and section.title %}{{ section.title }} — {{ config.title }}{% else %}{{ config.title }}{% endif %}
  {% if section is defined and section.description %}{{ section.description }}{% else %}{{ config.description }}{% endif %}


  Zola
  {{ last_updated | date(format="%+") }}
  {{ feed_url | safe }}

    Bastien Gallay
    {{ config.base_url | safe }}

{%- for page in pages %}

    {{ page.title }}
    {{ page.date | date(format="%+") }}
    {{ page.updated | default(value=page.date) | date(format="%+") }}

    {{ page.permalink | safe }}
    {%- if page.description %}
    {{ page.description }}
    {%- endif %}
    {#- xml:base : filet de sécurité pour toute URL relative restée dans le
        contenu (assets colocalisés) — les lecteurs conformes la résolvent
        contre le permalink de la page, pas contre l'URL du feed. -#}
    {{ page.content }}

{%- endfor %}
